package in.tucor.api.buyer; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="buyer_orders") public class BuyerOrder {@Id public UUID id;@Column(name="public_id") public String publicId;@Column(name="buyer_id") public UUID buyerId;@Column(name="listing_id") public UUID listingId;@Column(name="volume_liters") public int volumeLiters;@Column(name="price_per_liter") public BigDecimal pricePerLiter;@Column(name="total_amount") public BigDecimal totalAmount;public String status;@Column(name="delivery_address") public String deliveryAddress;public String notes;@Column(name="pickup_date") public LocalDate pickupDate;@Column(name="delivery_date") public LocalDate deliveryDate;@Column(name="payment_due") public LocalDate paymentDue;@Column(name="invoice_number") public String invoiceNumber;@Column(name="created_at") public Instant createdAt;@Column(name="updated_at") public Instant updatedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}}